// GURUJI — MantrasDB: client-side store for the Mantras & Stotras library.
// Reads the seed from mantras-data.js (generated), caches in localStorage and
// syncs with the /api/mantras endpoints when served over HTTP.
// This file is hand-maintained; mantras-data.js is regenerated by the server.

// Database abstraction with localStorage sync and optional HTTP API integration
const MantrasDB = {
  data: [],

  init() {
    try {
      const local = localStorage.getItem('guruji_mantras_library_v1');
      if (local) {
        const abs = (v) => (typeof v === 'string' && v.startsWith('assets/') ? '/' + v : v);
        this.data = JSON.parse(local).map(m => ({ ...m, image: abs(m.image), audio: abs(m.audio) }));
      } else {
        this.data = [...GURUJI_MANTRAS_SEED];
        this.saveLocal();
      }
    } catch (e) {
      console.warn('LocalStorage unavailable, using seed data:', e);
      this.data = [...GURUJI_MANTRAS_SEED];
    }

    // Attempt background sync with server if running on HTTP
    if (window.location.protocol.startsWith('http')) {
      fetch('/api/mantras')
        .then(res => res.ok ? res.json() : null)
        .then(serverData => {
          if (serverData && Array.isArray(serverData.mantras) && serverData.mantras.length > 0) {
            // older records stored page-relative asset paths; pages now live at nested URLs
            const abs = (v) => (typeof v === 'string' && v.startsWith('assets/') ? '/' + v : v);
            this.data = serverData.mantras.map(m => ({ ...m, image: abs(m.image), audio: abs(m.audio) }));
            this.saveLocal();
            document.dispatchEvent(new CustomEvent('mantras:updated'));
          }
        })
        .catch(() => {
          // Server offline or file protocol, continue with local data
        });
    }
  },

  getAll() {
    return this.data.filter(m => m.published !== false);
  },

  getAllAdmin() {
    return this.data;
  },

  getById(id) {
    return this.data.find(m => m.id === id || m.slug === id);
  },

  getFeatured() {
    return this.data.filter(m => m.featured && m.published !== false);
  },

  getRecent(limit = 4) {
    return [...this.data]
      .filter(m => m.published !== false)
      .sort((a, b) => new Date(b.created_at) - new Date(a.created_at))
      .slice(0, limit);
  },

  getByCategory(catId) {
    return this.data.filter(m => m.published !== false && (m.category === catId || (m.categories && m.categories.includes(catId))));
  },

  saveLocal() {
    try {
      localStorage.setItem('guruji_mantras_library_v1', JSON.stringify(this.data));
    } catch (e) {
      console.error('Failed to save to localStorage:', e);
    }
  },

  // Admin PIN is kept for this browser tab only and checked by the server on every write
  adminHeaders() {
    const pin = sessionStorage.getItem('guruji_admin_pin') || '';
    return { 'Content-Type': 'application/json', 'X-Admin-Pin': pin };
  },

  isServed() { return window.location.protocol.startsWith('http'); },

  async send(url, method, body) {
    const res = await fetch(url, { method, headers: this.adminHeaders(), body: body ? JSON.stringify(body) : undefined });
    const data = await res.json().catch(() => ({}));
    if (res.status === 401) sessionStorage.removeItem('guruji_admin_pin');
    if (!res.ok) throw new Error(data.error || `Request failed (${res.status})`);
    return data;
  },

  async addMantra(mantra) {
    mantra.id = mantra.id || 'mantra-' + Date.now();
    mantra.slug = mantra.slug || mantra.id;
    mantra.published = mantra.published !== false;
    if (this.isServed()) {
      const { mantra: saved } = await this.send('/api/mantras', 'POST', mantra);
      mantra = saved;
    } else {
      mantra.created_at = mantra.updated_at = new Date().toISOString();
    }
    this.data.unshift(mantra);
    this.saveLocal();
    return mantra;
  },

  async updateMantra(id, updates) {
    const idx = this.data.findIndex(m => m.id === id);
    if (idx === -1) return null;
    let next = { ...this.data[idx], ...updates, updated_at: new Date().toISOString() };
    if (this.isServed()) {
      const { mantra } = await this.send('/api/mantras/' + encodeURIComponent(id), 'PUT', next);
      next = mantra;
    }
    this.data[idx] = next;
    this.saveLocal();
    return next;
  },

  async deleteMantra(id) {
    const idx = this.data.findIndex(m => m.id === id);
    if (idx === -1) return false;
    if (this.isServed()) await this.send('/api/mantras/' + encodeURIComponent(id), 'DELETE');
    this.data.splice(idx, 1);
    this.saveLocal();
    return true;
  }
};

// Initialize DB on script load
MantrasDB.init();
